import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int ax = sc.nextInt(), ay = sc.nextInt();
        int bx = sc.nextInt(), by = sc.nextInt();
        int cx = sc.nextInt(), cy = sc.nextInt();
        int px = sc.nextInt(), py = sc.nextInt();
        int qx = sc.nextInt(), qy = sc.nextInt();

        boolean pInside = isInside(ax, ay, bx, by, cx, cy, px, py);
        boolean qInside = isInside(ax, ay, bx, by, cx, cy, qx, qy);

        if (pInside != qInside) {
            System.out.println("OK");
        } else {
            System.out.println("NG");
        }
    }

    static boolean isInside(int ax, int ay, int bx, int by, int cx, int cy, int px, int py) {
        long d1 = cross(bx - ax, by - ay, px - ax, py - ay);
        long d2 = cross(cx - bx, cy - by, px - bx, py - by);
        long d3 = cross(ax - cx, ay - cy, px - cx, py - cy);

        boolean hasNeg = (d1 < 0) || (d2 < 0) || (d3 < 0);
        boolean hasPos = (d1 > 0) || (d2 > 0) || (d3 > 0);

        // All cross products have the same sign -> inside
        return !(hasNeg && hasPos);
    }

    static long cross(long x1, long y1, long x2, long y2) {
        return x1 * y2 - y1 * x2;
    }
}

