import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static long cross(long ax, long ay, long bx, long by, long cx, long cy) {
        return (bx - ax) * (cy - ay) - (by - ay) * (cx - ax);
    }

    static boolean insideTriangle(long ax, long ay, long bx, long by, long cx, long cy, long px, long py) {
        long c1 = cross(ax, ay, bx, by, px, py);
        long c2 = cross(bx, by, cx, cy, px, py);
        long c3 = cross(cx, cy, ax, ay, px, py);

        boolean allPos = c1 > 0 && c2 > 0 && c3 > 0;
        boolean allNeg = c1 < 0 && c2 < 0 && c3 < 0;
        return allPos || allNeg;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        long ax = fs.nextLong();
        long ay = fs.nextLong();
        long bx = fs.nextLong();
        long by = fs.nextLong();
        long cx = fs.nextLong();
        long cy = fs.nextLong();
        long dx = fs.nextLong();
        long dy = fs.nextLong();
        long ex = fs.nextLong();
        long ey = fs.nextLong();

        boolean dInside = insideTriangle(ax, ay, bx, by, cx, cy, dx, dy);
        boolean eInside = insideTriangle(ax, ay, bx, by, cx, cy, ex, ey);

        System.out.println(dInside ^ eInside ? "OK" : "NG");
    }
}

